catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;
    var caseVars = ['source_case', 'target_case'];
    var userVars = ['source_user', 'target_user'];
    var i;
    for (i = 0; i < caseVars.length; i++) g_form.setDisplay(caseVars[i], newValue === 'case');
    for (i = 0; i < userVars.length; i++) g_form.setDisplay(userVars[i], newValue === 'user');
    g_form.setMandatory('source_case', newValue === 'case');
    g_form.setMandatory('target_case', newValue === 'case');
    g_form.setMandatory('target_user', newValue === 'user');
    g_form.clearValue('assets');
    if (newValue === 'case') {
        g_form.clearValue('source_user');
        g_form.clearValue('target_user');
    } else {
        g_form.clearValue('source_case');
        g_form.clearValue('target_case');
    }
}
